  function translate(value, language = "en", depth = 0) {
    if (typeof value !== "string" || !value || depth > 8) return value;
    const en = language === "en";
    const dictionary = en ? toEnglish : toRussian;
    if (dictionary.has(value)) return dictionary.get(value);
    const tr = text => translate(text, language, depth + 1);
    for (const pattern of patterns) {
      const match = value.match(pattern[en ? 0 : 1]);
      if (match) return pattern[en ? 2 : 3](match, tr);
    }
    // Several status fields join independent system sentences; translate each without touching their data captures.
    const sentences = value.split(/((?<=[.!?…])\s+(?=[A-ZА-ЯЁ]))/u);
    if (sentences.length > 1) return sentences.map((part, index) => index % 2 ? part : tr(part)).join("");
    if (value.includes("\n")) return value.split(/(\r?\n)/u).map((part, index) => index % 2 ? part : tr(part)).join("");
    return value;
  }
  globalThis.GoodogI18n = Object.freeze({ translate });
